from pathlib import Path

STYLE = '''
:root{font-family:"Microsoft YaHei UI","Microsoft YaHei",system-ui,sans-serif;color:#17222b;background:#f5f7f9}*{box-sizing:border-box}body{margin:0}a{color:#16736c;text-decoration:none}button,input{font:inherit}button,.button{padding:10px 16px;border:1px solid #cbd8dc;border-radius:10px;background:white;color:#17222b;cursor:pointer}button.primary{background:#176d65;color:white;border-color:#176d65}.wrap{max-width:1160px;margin:28px auto;padding:0 20px}.panel{background:white;border:1px solid #e1e6ea;border-radius:16px;padding:24px}.bar{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px}.nav{display:flex;align-items:center;gap:16px}.small{font-size:13px;color:#69747d}h1{font-size:25px;margin:0 0 8px}h2{font-size:17px;margin:0 0 12px}label{display:block;font-size:14px;margin:18px 0 8px}input{width:100%;border:1px solid #cad3da;border-radius:9px;padding:12px}#message{color:#a12626;min-height:22px;font-size:14px}.login{max-width:450px;margin:10vh auto}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(285px,1fr));gap:18px}.card{overflow:hidden;background:white;border:1px solid #e1e6ea;border-radius:14px}.card img{width:100%;aspect-ratio:1;object-fit:contain;background:#eef1f4}.card-body{padding:16px}.prompt{white-space:pre-wrap;word-break:break-word;max-height:120px;overflow:auto;line-height:1.6;margin:12px 0}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.pill{font-size:12px;padding:4px 8px;background:#e9f4f1;border-radius:20px;color:#196f64}details{margin-top:12px}pre{max-height:300px;overflow:auto;white-space:pre-wrap;font-size:12px;background:#f5f7f9;padding:12px;border-radius:8px}@media(max-width:600px){.bar{align-items:flex-start;flex-direction:column}.login{margin:7vh 16px}.wrap{padding:0 14px}.nav{gap:12px}}
'''

AUTH_JS = (Path(__file__).parent / 'auth-ui.js').read_text(encoding='utf-8')

def auth_page(name):
    return (Path(__file__).parent / name).read_text(encoding='utf-8').replace('STYLE', STYLE, 1).replace('AUTH_JS', AUTH_JS, 1)

LOGIN = auth_page('login-passkey.html')
REGISTER = auth_page('register-passkey.html')
PASSKEY_MANAGEMENT = auth_page('manage-passkeys.html')

HISTORY = '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>历史记录 · Qwen-Image</title><style>STYLE</style></head><body><main class="wrap"><header class="bar"><div><h1>历史记录</h1><div class="small">原图、提示词、生成参数和结果自动保存，刷新或重启后仍可查看。</div></div><nav class="nav"><a href="/">文生图</a><a href="/edit">改图</a><a href="/passkeys">Passkey</a><button id="refresh">刷新</button><button id="logout">退出登录</button></nav></header><div id="message" role="alert"></div><section id="grid" class="grid"></section><div class="row" style="justify-content:center;margin:24px"><button id="previous">上一页</button><span id="page" class="small"></span><button id="next">下一页</button></div></main><script>
let csrf='',page=1,total=0;const state={submitting:'正在提交',queued:'排队中',generating:'正在生成',completed:'已完成',failed:'失败',cancelled:'已取消'};
async function api(url,options={}){options.headers={...options.headers,'X-Qwen-CSRF':csrf};const response=await fetch(url,options);if(response.status===401){location.href='/login';throw new Error('请重新登录');}if(!response.ok)throw new Error('请求失败');return response.json();}
function element(tag,text,cls){const node=document.createElement(tag);if(text!=null)node.textContent=text;if(cls)node.className=cls;return node;}
async function refresh(){try{const result=await api('/archive/records?page='+page);total=result.total;const grid=document.getElementById('grid');grid.replaceChildren();if(!result.records.length)grid.append(element('div','暂无历史记录。先生成一张图片，记录会自动保存。','panel'));for(const item of result.records){const card=element('article',null,'card');if(item.images.length){const image=element('img');image.src='/archive/records/'+item.id+'/images/0';image.alt='生成图片';image.loading='lazy';card.append(image);}if(item.references?.length){const originals=element('details');originals.style.padding='12px 16px';originals.append(element('summary','查看上传原图'));for(const ref of item.references){const original=element('img');original.src='/archive/records/'+item.id+'/references/'+ref.index;original.alt='上传原图';original.loading='lazy';originals.append(original);}card.append(originals);}const body=element('div',null,'card-body');const row=element('div',null,'row');row.append(element('span',item.mode==='editing'?'参考图改图':'文生图','pill'));row.append(element('span',state[item.status]||item.status,'pill'),element('span',new Date(item.created*1000).toLocaleString('zh-CN'),'small'));body.append(row,element('div',item.request.prompt,'prompt'));if(item.error)body.append(element('div',typeof item.error==='string'?item.error:JSON.stringify(item.error),'small'));const actions=element('div',null,'row');for(const image of item.images){const link=element('a','下载图片 '+(image.index+1));link.href='/archive/records/'+item.id+'/images/'+image.index+'?download=1';link.download='qwen-'+item.id+'.'+image.format;actions.append(link);}for(const ref of item.references||[]){const link=element('a','下载原图');link.href='/archive/records/'+item.id+'/references/'+ref.index+'?download=1';actions.append(link);}if(item.images.length){const edit=element('a','以此改图');edit.href='/edit?record='+item.id;actions.append(edit);}const meta=element('a','下载提示词与参数');meta.href='/archive/records/'+item.id+'/export';meta.download='qwen-'+item.id+'.json';actions.append(meta);body.append(actions);const details=element('details');details.append(element('summary','查看生成参数'),element('pre',JSON.stringify(item.request,null,2)));body.append(details);card.append(body);grid.append(card);}document.getElementById('page').textContent='第 '+page+' 页 · 共 '+total+' 条';document.getElementById('previous').disabled=page===1;document.getElementById('next').disabled=page*30>=total;document.getElementById('message').textContent='';}catch(error){document.getElementById('message').textContent=error.message;}}
document.getElementById('refresh').onclick=refresh;document.getElementById('previous').onclick=()=>{if(page>1){page--;refresh();}};document.getElementById('next').onclick=()=>{page++;refresh();};document.getElementById('logout').onclick=async()=>{await api('/logout',{method:'POST'});location.href='/login';};api('/session').then(session=>{csrf=session.csrf;refresh();});
</script></body></html>'''.replace('STYLE', STYLE)

NATIVE_NAV = '''<style>.lan-nav{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 24px;border-bottom:1px solid #e1e6ea;background:white;font-family:"Microsoft YaHei UI",system-ui,sans-serif}.lan-nav div{display:flex;gap:18px;align-items:center}.lan-nav a{color:#16736c;text-decoration:none}.lan-nav button{font:inherit;background:white;border:1px solid #cbd8dc;border-radius:8px;padding:6px 12px;cursor:pointer}.lan-nav small{color:#68767e}@media(max-width:650px){.lan-nav{padding:12px 16px;align-items:flex-start;flex-direction:column}}</style><nav class="lan-nav"><div><strong>局域网加密服务</strong><small>自动保存原图、提示词与结果</small></div><div><a href="/edit">改图</a><a href="/history">历史记录</a><a href="/passkeys">Passkey</a><button id="lan-logout">退出登录</button></div></nav><script>
(() => {let csrf='';const original=window.fetch.bind(window);const ready=original('/session').then(r=>r.json()).then(data=>{csrf=data.csrf;});window.fetch=async(input,options={})=>{await ready;const method=(options.method||'GET').toUpperCase();if(method!=='GET'&&method!=='HEAD'){options={...options,headers:{...options.headers,'X-Qwen-CSRF':csrf}};}const response=await original(input,options);if(response.status===401)location.href='/login';return response;};document.getElementById('lan-logout').onclick=async()=>{await window.fetch('/logout',{method:'POST'});location.href='/login';};})();
</script>'''

